import * as AWS from "@alchemy.run/aws";
import * as Effect from "effect/Effect";

export default class JobFunction extends AWS.Lambda.Function<JobFunction>()(
  "JobFunction",
  {
    main: import.meta.filename,
    functionUrl: true,
  },
  Effect.succeed({ fetch: Effect.succeed("ok") }),
) {}

import * as Cloudflare from "@alchemy.run/cloudflare";

export default class Backend extends Cloudflare.Worker<Backend>()(
  "Backend",
  {
    main: import.meta.filename,
    workersDev: false, // no workers.dev URL; we use the service binding instead
  },
) {}

import { HttpApiClient } from "effect/unstable/httpapi";
import { ShortyApi } from "./ShortyApi.vibe";

export const API_URL = import.meta.env.VITE_API_URL as string;

// A typed client derived from the same `ShortyApi` value the Worker serves.
const makeClient = HttpApiClient.make(ShortyApi, { baseUrl: API_URL });
export const client = makeClient;

import ReactDOM from "react-dom/client";

const API_URL = import.meta.env.VITE_API_URL ?? "http://localhost:8787";

ReactDOM.createRoot(document.getElementById("root")!).render(<p>{API_URL}</p>);

import * as AWS from "@alchemy.run/aws";
import * as Effect from "effect/Effect";

export const program = Effect.gen(function* () {
  const reportTask = yield* AWS.ECS.Task("ReportTask", {
    context: `${import.meta.dirname}/src/report`,
    cpu: 256,
  });
  return reportTask;
});

import * as Effect from "effect/Effect";
import * as Path from "effect/Path";

export const root = Effect.gen(function* () {
  const path = yield* Path.Path;
  const repositoryRoot = path.resolve(import.meta.dirname, "..");
  return repositoryRoot;
});

import { moduleExtension } from "../Util/Node.ts";

export const ServerProviderLocal = () =>
  LocalProvider.make(
    Server,
    import.meta.resolve(`./ServerLocal${moduleExtension(import.meta.url)}`, import.meta.url),
  );

import { moduleExtension } from "./Util.ts";

export const LocalFunctionProvider = () =>
  LocalProvider.make(Function, import.meta.resolve(`./LocalFunction${moduleExtension(import.meta.url)}`));
